    const getList = () => pdoc.querySelector("#completion_prompt_manager_list");
    const esc = (s) => (pwin.CSS?.escape ? CSS.escape(s) : String(s).replace(/["\\]/g, "\\$&"));
    const findById = (id) => {
      const list = getList(); if (!list) return [];
      return [...list.querySelectorAll(`li[data-pm-identifier="${esc(id)}"]`)];
    };
    const findByKeyword = (kw) => {
      const list = getList(); if (!list) return [];
      return [...list.querySelectorAll("li")].filter(li => {
        const n = li.querySelector("[data-pm-name]"); return n && n.getAttribute("data-pm-name") === kw;
      });
    };
    const findPrompt = (id, kw) => { const r = findById(id); return r.length ? r : findByKeyword(kw); };
    const isOn = (li) => li && !li.classList.contains("completion_prompt_manager_prompt_disabled");
    const clickToggle = (li) => {
      const b = li.querySelector(".prompt-manager-toggle-action") || li.querySelector("[data-action='toggle']") || li.querySelector("button");
      if (b) b.click();
    };
    const ensureOn = (id, kw) => findPrompt(id, kw).forEach(li => { if (!isOn(li)) clickToggle(li); });
    const ensureOff = (id, kw) => findPrompt(id, kw).forEach(li => { if (isOn(li)) clickToggle(li); });
    const isKeyOn = (id, kw) => { const it = findPrompt(id, kw); return it.length > 0 && it.every(isOn); };

