.erii-item:hover{transform:translateX(3px);border-color:var(--mark);background:rgba(224,107,94,.10);box-shadow:0 4px 16px rgba(0,0,0,.42)}
.erii-item:hover::before{opacity:1}
.erii-item:active{transform:translateX(3px) scale(.985)}
.erii-link{display:flex;align-items:flex-start;gap:12px;padding:11px 14px 11px 16px;text-decoration:none;color:#E7E0D4;font-size:.94em;line-height:1.7;cursor:pointer}
.erii-no{flex-shrink:0;width:24px;height:24px;border-radius:50%;border:1px solid var(--mark);color:var(--mark);font-family:"Long Cang","Kaiti SC","STKaiti","KaiTi","Noto Serif SC",serif;font-size:.95em;display:flex;align-items:center;justify-content:center;margin-top:2px;transition:transform .3s,background .3s,color .3s;background:transparent}
.erii-item:hover .erii-no{transform:rotate(-8deg) scale(1.08)}
.erii-item.done .erii-no{background:var(--mark);color:#221E29}
.erii-ft{padding:6px 18px 12px;text-align:center;font-family:"Long Cang","Kaiti SC","STKaiti","KaiTi","Noto Serif SC",serif;font-size:.92em;color:#A99F91;letter-spacing:2px;opacity:.8;transition:color .3s}
.erii-ft.flash{color:#E06B5E}
@media(max-width:480px){.erii-hd{font-size:1.02em;padding:11px 14px 7px}.erii-link{padding:10px 11px 10px 13px;font-size:.9em;gap:10px}}
@media(prefers-reduced-motion:reduce){.erii-item,.erii-no{transition:none}.erii-item:hover{transform:none}}
</style>
</head>
<body>
<div class="erii-paper">
<div class="erii-hd"><span class="ico">✿</span>绘梨衣的纸条<span class="ico">✿</span></div>
<ul class="erii-list" id="erii-opts">
<li class="erii-item"><a href="javascript:void(0);" class="erii-link" data-opt='$1'><span class="erii-no">一</span><span>$1</span></a></li>
<li class="erii-item"><a href="javascript:void(0);" class="erii-link" data-opt='$2'><span class="erii-no">二</span><span>$2</span></a></li>
<li class="erii-item"><a href="javascript:void(0);" class="erii-link" data-opt='$3'><span class="erii-no">三</span><span>$3</span></a></li>
<li class="erii-item"><a href="javascript:void(0);" class="erii-link" data-opt='$4'><span class="erii-no">四</span><span>$4</span></a></li>
</ul>
<div class="erii-ft" id="erii-ft">选一条，或者写你自己的</div>
</div>
<script>
(function(){
var ft=document.getElementById('erii-ft');
function fill(t){if(!t||!t.trim())return false;
try{var i=window.parent.document.querySelector('#send_textarea');
if(i){var v=i.value.trim();i.value=v?v+'\n'+t:t;i.dispatchEvent(new Event('input',{bubbles:true}));return true;}}catch(e){console.error(e);}
return false;}
var list=document.getElementById('erii-opts');
if(list){list.addEventListener('click',function(e){
var l=e.target.closest('.erii-link');if(!l)return;
var t=l.dataset.opt||'';
if(t.charAt(0)==='['&&t.charAt(t.length-1)===']')t=t.slice(1,-1);
if(!fill(t))return;
var item=l.closest('.erii-item'),no=l.querySelector('.erii-no'),old=no.textContent;
item.classList.add('done');no.textContent='✓';
ft.textContent='✿ 已写进输入框，想改随便改';ft.classList.add('flash');
setTimeout(function(){item.classList.remove('done');no.textContent=old;
ft.textContent='选一条，或者写你自己的';ft.classList.remove('flash');},1800);
});}
})();
</script>
</body>
</html>
