<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<link rel="preconnect" href="https://fonts.loli.net">
<link rel="preconnect" href="https://gstatic.loli.net" crossorigin>
<link href="https://fonts.loli.net/css2?family=Noto+Serif+SC:wght@400;700&family=Long+Cang&family=Liu+Jian+Mao+Cao&family=ZCOOL+XiaoWei&display=swap" rel="stylesheet">
<style>
*{box-sizing:border-box}
body{margin:0;background:transparent}
.paper-art{max-width:min(560px,92%);margin:14px auto;position:relative;line-height:1.95;font-size:.98em;white-space:pre-wrap;word-wrap:break-word;transition:transform .3s ease}
/* 信纸(默认) */
.paper-art.t-letter{background:#FBF7EE;background-image:repeating-linear-gradient(0deg,transparent,transparent 27px,rgba(176,141,87,.14) 27px,rgba(176,141,87,.14) 28px);border:1px solid rgba(176,141,87,.5);border-radius:4px;padding:26px 30px 30px;font-family:"ZCOOL XiaoWei","Kaiti SC","STKaiti","KaiTi",serif;color:#3D362E;box-shadow:0 4px 16px rgba(93,63,38,.12),inset 0 0 34px rgba(176,141,87,.07);transform:rotate(-.4deg)}
.paper-art.t-letter:hover{transform:rotate(0)}
.paper-art.t-letter::before{content:"";position:absolute;top:-7px;left:50%;transform:translateX(-50%) rotate(-2.5deg);width:64px;height:19px;background:rgba(192,69,60,.30);border:1px dashed rgba(192,69,60,.45);box-shadow:0 1px 4px rgba(192,69,60,.18)}
.paper-art.t-letter::after{content:"✿";position:absolute;bottom:9px;right:15px;font-family:"Long Cang",serif;color:rgba(192,69,60,.35);font-size:1.25em;transform:rotate(14deg)}
/* 屏幕 */
.paper-art.t-screen{background:#171B22;border:1px solid #313B49;border-radius:14px;padding:38px 24px 26px;font-family:"PingFang SC","Microsoft YaHei",-apple-system,sans-serif;color:#D6DEE8;font-size:.92em;line-height:1.8;box-shadow:0 6px 22px rgba(0,0,0,.45),inset 0 0 0 1px rgba(255,255,255,.03)}
.paper-art.t-screen::before{content:"";position:absolute;top:15px;left:22px;width:8px;height:8px;border-radius:50%;background:#3E4B5C;box-shadow:14px 0 0 #3E4B5C,28px 0 0 #3E4B5C}
.paper-art.t-screen::after{content:"";position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,rgba(120,160,220,.35),transparent)}
/* 报纸 */
.paper-art.t-news{background:#F2EEE2;border-top:3px double #55504A;border-bottom:3px double #55504A;padding:22px 26px;font-family:"Noto Serif SC","Songti SC","SimSun",serif;color:#33302B;font-size:.93em;line-height:1.78;text-align:justify;box-shadow:0 3px 12px rgba(60,55,45,.14)}
.paper-art.t-news::before{content:"◈ 剪 报 ◈";position:absolute;top:5px;right:12px;font-size:.72em;letter-spacing:3px;color:rgba(85,80,74,.55)}
/* 告示板 */
.paper-art.t-board{background:linear-gradient(135deg,#8A6A4A,#75563B);border:6px solid #5C432E;border-radius:6px;padding:22px;box-shadow:0 5px 18px rgba(50,35,20,.4);color:transparent}
.paper-art.t-board .pin-note{background:#FBF7EE;padding:18px 20px;border-radius:2px;color:#3D362E;font-family:"ZCOOL XiaoWei","Kaiti SC","STKaiti","KaiTi",serif;box-shadow:0 3px 10px rgba(40,25,10,.35);transform:rotate(.6deg);position:relative}
.paper-art.t-board .pin-note::before{content:"📌";position:absolute;top:-11px;left:50%;transform:translateX(-50%);font-size:1.1em}
/* 卷轴 */
.paper-art.t-scroll{background:#F6ECD6;background-image:linear-gradient(90deg,rgba(155,120,70,.14) 0%,transparent 7%,transparent 93%,rgba(155,120,70,.14) 100%);border:none;border-radius:2px;padding:30px 34px;font-family:"Kaiti SC","STKaiti","KaiTi","ZCOOL XiaoWei",serif;color:#4A3A26;box-shadow:0 4px 14px rgba(93,63,38,.18)}
.paper-art.t-scroll::before,.paper-art.t-scroll::after{content:"";position:absolute;left:-8px;right:-8px;height:12px;background:linear-gradient(180deg,#7A5A38,#5C432E);border-radius:6px;box-shadow:0 2px 6px rgba(50,35,20,.4)}
.paper-art.t-scroll::before{top:-7px}
.paper-art.t-scroll::after{bottom:-7px}
.paper-art strong{font-weight:normal;font-family:"Long Cang","Kaiti SC","STKaiti",serif;color:#C0453C;font-size:1.08em}
.paper-art.t-screen strong{color:#8FB8F0;font-family:inherit}
@media(max-width:480px){.paper-art{font-size:.92em}.paper-art.t-letter{padding:22px 18px 26px}.paper-art.t-screen{padding:34px 16px 20px}.paper-art.t-news{padding:18px 16px}.paper-art.t-scroll{padding:26px 20px}}
</style>
</head>
<body data-ptype="$1">
<div class="paper-art" id="paper"><div class="pin-note">$2</div></div>
<script>
(function(){
var t=(document.body.dataset.ptype||'letter').toLowerCase();
if(['letter','screen','news','board','scroll'].indexOf(t)<0)t='letter';
var el=document.getElementById('paper');el.classList.add('t-'+t);
if(t!=='board'){var n=el.querySelector('.pin-note');while(n.firstChild)el.insertBefore(n.firstChild,n);n.remove();}
})();
</script>
</body>
</html>
